package dev.packconverter.core.slicer;

import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import dev.packconverter.core.io.Json;

import java.io.IOException;
import java.io.InputStream;
import java.util.HashMap;
import java.util.Map;

/**
 * Sheet regions didn't always hold the sprite the slicers cut from them: before 1.14 the part of inventory.png
 * that later became the effect background held the effect icons. For every slicer output, the first pack format
 * whose vanilla sheet has that sprite in that region (generated by SliceSinceGenerator from vanilla sheets of
 * every version). Packs made for older formats skip the output, so the game keeps its own sprite.
 */
public final class SliceSince {
	private static Map<String, Integer> table;

	private SliceSince() {
	}

	/** First format whose sheet has this output's sprite, or null if it was always there. */
	public static Integer format(String outputPath) {
		return table().get(outputPath);
	}

	private static synchronized Map<String, Integer> table() {
		if (table == null) {
			Map<String, Integer> map = new HashMap<>();
			try (InputStream in = SliceSince.class.getResourceAsStream("/packconverter/slice-since.json")) {
				if (in != null) {
					JsonObject root = Json.obj(Json.parse(in.readAllBytes()));
					JsonObject since = Json.obj(root, "since");
					if (since != null) for (Map.Entry<String, JsonElement> e : since.entrySet()) map.put(e.getKey(), e.getValue().getAsInt());
				}
			} catch (IOException ignored) {
			}
			table = map;
		}
		return table;
	}
}
